const text = items[0].json.output || items[0].json.text || "";
const statusMatch = text.match(/\[(NEW LEAD|CONTACTED|CONVERTED|JUNK)\]/i);
const cleanMessage = text.replace(/\[(NEW LEAD|CONTACTED|CONVERTED|JUNK)\]/gi, "").trim();

return [{
  json: {
    cleanMessage: cleanMessage,
    newStatus: statusMatch ? statusMatch[1].toUpperCase() : 'NEW LEAD'
  }
}];
